def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Gentle opening: establish cooperation, tolerate a single early defection.
    if n < 4:
        return 'C'

    # Gather statistics in one pass to stay cheap.
    cc = cd = dc = dd = 0
    my_def = 0
    opp_def = 0
    last_my = last_opp = 'C'
    prev_my = prev_opp = 'C'
    for i in range(n):
        m, o = history[i]
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1
        else:
            my_def += 1
            if o == 'C':
                dc += 1
            else:
                dd += 1
        if o == 'D':
            opp_def += 1
        if i == n - 2:
            prev_my, prev_opp = m, o
        if i == n - 1:
            last_my, last_opp = m, o

    opp_coop = n - opp_def
    opp_rate = opp_coop / float(n)

    # Consecutive runs at the tail.
    run_opp_def = 0
    run_opp_c = 0
    run_both_d = 0
    for i in range(n - 1, -1, -1):
        o = history[i][1]
        m = history[i][0]
        if o == 'D':
            run_opp_def += 1
        else:
            break
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            run_opp_c += 1
        else:
            break
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            run_both_d += 1
        else:
            break

    # Very late game: once cooperation is established, avoid risky probes.
    remaining = 100 - n
    if remaining <= 2:
        if opp_rate >= 0.5:
            return 'C'
        return 'D'

    # Opponent has been cooperative: keep rewarding them, probe sparingly.
    if opp_rate >= 0.85:
        if last_opp == 'C':
            # Rare probe to test for hidden exploiters, but never two in a row.
            if last_my == 'C' and remaining > 5 and n % 19 == 0 and rng.random() < 0.08:
                return 'D'
            return 'C'
        # Isolated defection from a generally nice opponent: forgive once.
        if last_my == 'C':
            if run_opp_def >= 2:
                return 'D'
            if rng.random() < 0.7:
                return 'C'
            return 'D'
        # We just defected (probably a probe) and they punished; return to C.
        if run_opp_def == 1 and rng.random() < 0.85:
            return 'C'
        return 'D'

    # Opponent is severely exploitative: defend, but keep an escape hatch.
    if opp_rate <= 0.2:
        if run_opp_def >= 5:
            if rng.random() < 0.06:
                return 'C'
            return 'D'
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    # Mixed opponent: tit-for-tat with forgiveness, plus defection recovery.
    if last_opp == 'D':
        # Heavy recent defection: retaliate firmly.
        if run_opp_def >= 3:
            return 'D'
        # We defected too: try to break the DD cycle quickly.
        if last_my == 'D':
            if run_both_d >= 2:
                return 'C' if rng.random() < 0.55 else 'D'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # They defected while we cooperated: punish but forgive if isolated.
        if run_opp_def == 1:
            if opp_rate >= 0.55 and rng.random() < 0.4:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last: reciprocate, avoid over-defecting.
    if last_my == 'D':
        return 'C'
    # Occasionally test a moderate opponent, but not near the end.
    if remaining > 15 and opp_rate < 0.55 and n % 23 == 0 and rng.random() < 0.12:
        return 'D'
    return 'C'
